  const line=(x1,y1,x2,y2,color=C.line,width=1,extra='')=>`<line x1="${fmt(x1)}" y1="${fmt(y1)}" x2="${fmt(x2)}" y2="${fmt(y2)}" stroke="${color}" stroke-width="${width}" ${extra}/>`;
