    'fundamentals-density':{label:'Supplied Physics Ch. 1, Eq. 1-8; OpenStax University Physics 1, §14.1',url:'https://openstax.org/books/university-physics-volume-1/pages/14-1-fluids-density-and-pressure'},
    'fundamentals-continuity':{label:'OpenStax University Physics 1, §14.5, Eqs. 14.13–14.15 and Fig. 14.27',url:'https://openstax.org/books/university-physics-volume-1/pages/14-5-fluid-dynamics'}
